// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(newOwner != actor);
        vm.assume(newOwner != address(0));
        vm.prank(address(0));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
